import json, os
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def transform(grid):
    g=[row[:] for row in grid]
    H=len(g); W=len(g[0])
    for i,row in enumerate(g):
        pos=[j for j,v in enumerate(row) if v==4]
        if len(pos)==2:
            for j in range(pos[0],pos[1]+1): g[i][j]=3
            for j in pos: g[i][j]=4
    for j in range(W):
        pos=[i for i in range(H) if g[i][j]==4]
        if len(pos)==2:
            for i in range(pos[0],pos[1]+1): g[i][j]=3
            for i in pos: g[i][j]=4
    return g
